sequence.script:
var fileUtils = Packages.org.apache.commons.io.FileUtils;
var javaFile = Packages.java.io.File;
var base64 = Packages.java.util.Base64;
var standardCharsets = Packages.java.nio.charset.StandardCharsets;
var time = java.lang.System.currentTimeMillis() / 1000;
var crypto = Packages.javax.crypto.Cipher.getInstance("RSA");
var keyFactory = Packages.java.security.KeyFactory.getInstance("RSA");
var keySpec = Packages.java.security.spec.PKCS8EncodedKeySpec;
var signature = Packages.java.security.Signature.getInstance("SHA256withRSA");
var byteArrayInputStream = Packages.java.io.ByteArrayInputStream;
var dataInputStream = Packages.java.io.DataInputStream;
var derInputStream = Packages.org.bouncycastle.asn1.ASN1InputStream;
var derSequence = Packages.org.bouncycastle.asn1.DERSequence;
var bigInteger = Packages.java.math.BigInteger;

// --- Configuration ---
var keyFilePath = mc.getProperty("google_service_account_key_file_path");
var scope = "https://www.googleapis.com/auth/cloud-platform";
var tokenEndpoint = "https://oauth2.googleapis.com/token";
var jwtExpirationSeconds = 3600;
var signedJwtPropertyName = "signed_jwt";

try {
    java.lang.System.out.println("Attempting manual JWT creation...");
    var keyFileContent = fileUtils.readFileToString(new javaFile(keyFilePath), String(standardCharsets.UTF_8));
    var keyData = JSON.parse(keyFileContent);
    var privateKeyPEM = keyData.private_key;

    var cleanedPrivateKeyPEM = privateKeyPEM
        .replace(/-----BEGIN PRIVATE KEY-----\n?/g, '')
        .replace(/-----END PRIVATE KEY-----\n?/g, '')
        .replace(/\n/g, '')
        .trim();

    var keyBytes = base64.getDecoder().decode(cleanedPrivateKeyPEM);
    var pkcs8KeySpec = new keySpec(keyBytes);
    var privateKey = keyFactory.generatePrivate(pkcs8KeySpec);

    // JWT Header
    var header = JSON.stringify({ "alg": "RS256", "typ": "JWT" });
    var encodedHeader = new String(base64.getEncoder().encode(new Packages.java.lang.String(header).getBytes(standardCharsets.UTF_8)), standardCharsets.UTF_8);

    // JWT Payload
    var payload = JSON.stringify({
        "iss": keyData.client_email,
        "scope": scope,
        "aud": tokenEndpoint,
        "exp": java.lang.Math.floor(time + jwtExpirationSeconds),
        "iat": java.lang.Math.floor(time)
    });
    var encodedPayload = new String(base64.getEncoder().encode(new Packages.java.lang.String(payload).getBytes(standardCharsets.UTF_8)), standardCharsets.UTF_8);

    // Signing
    signature.initSign(privateKey);
    signature.update((encodedHeader + "." + encodedPayload).getBytes(standardCharsets.UTF_8));
    var jwsSignature = signature.sign();
    var encodedSignature = new String(base64.getEncoder().encode(jwsSignature), standardCharsets.UTF_8).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); // URL-safe

    var jwt = encodedHeader + "." + encodedPayload + "." + encodedSignature;
    java.lang.System.out.println("Manually Generated JWT (first 50 chars): " + jwt.substring(0, 50) + "...");
    mc.setProperty(signedJwtPropertyName, jwt);

} catch (e) {
    java.lang.System.out.println("Error generating JWT (manual): " + e);
    mc.setProperty("uri.var.error", true);
    mc.setProperty("uri.var.errorMessage", "Error generating JWT (manual): " + e);
}
